__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

from velocity_communicator.support_services.private.inventory_methods import InventoryPrivate
from copy import deepcopy


class CRMaintenancePrivate(InventoryPrivate):
    """
        Class with definicion of private methods related to
        CMaintenance module.
    """

    def _is_user_technician(self):
        profile_id = self.get_current_user()["id"]
        user_groups = self.get_groups(limit=200, forUser=profile_id)
        group_id = False
        for group in user_groups["userGroups"]:
            if group["name"] == "Technician":
                group_id = group["id"]
        if group_id:
            return True

    def _is_user_admin(self):
        current_user = self.get_current_user()
        if current_user["role"] == "ADMIN":
            return True
        else:
            return False

    def _execute_cable_update(self,
                              cable_id,
                              cable_to_change,
                              current_name,
                              new_name):
        body = self._change_cable_json(cable_to_change, new_name)
        response = self.update_cable(cable_id, body)
        if response["name"] == new_name:
            msg = f"Cable name changed: '{current_name}' to '{new_name}'."
            self.logger.info(msg)
            return True
        else:
            msg = "Error during cable name change from " \
                f"{current_name} to {new_name}."
            self.logger.error(msg)
            return False

    def _get_cable_body(self, current_name):
        cable_details = self.get_cables(filter=f"name::{current_name}")
        if cable_details['cables']:
            cable_id = cable_details["cables"][0]["id"]
            cable_to_change = self.get_cable(cable_id)
            return cable_to_change, cable_id
        else:
            msg = f"Not found cable: {current_name}"
            self.logger.error(msg)

    def _get_cable_type_body(self, cable_type_name: str):
        cable_types = self.get_cable_types(includeProperties=True)
        new_cable_type = next(
            (
                cable_type
                for cable_type in cable_types["cableTypes"]
                if cable_type_name == cable_type["name"]
            ),
            None
        )
        if new_cable_type:
            return new_cable_type, new_cable_type["id"]
        else:
            self.logger.error(f"Cable type not found: {cable_type_name}")
            raise Exception(f"Cable type not found: {cable_type_name}")

    def _change_cable_type(self, cable_name: str, cable_type_name: str):
        cable_data, cable_id = self._get_cable_body(cable_name)
        original_cable_data = cable_data
        cable_type_data, cable_type_id = self._get_cable_type_body(cable_type_name)
        cable_data["cableTypeId"] = cable_type_id
        for prop in cable_data["properties"]:
            for group in cable_type_data["propertyGroups"]:
                for item in group["properties"]:
                    if prop["name"] == item["name"]:
                        prop["definitionId"] = item["id"]

        # Updating cable via self.update_cable() does not work, need to delete and create with the correct type
        res = self.delete_cable(cable_id)
        if res:
            self.logger.error(f"Failed to delete cable {cable_name}.\n"
                              f"Error: {res['status']} - {res['errorId']} - {res['message']}")
            return
        self.logger.info(f"Cable {cable_name} deleted.")
        res = self.create_cable(cable_data)
        if "status" in res:
            self.logger.error(f"Failed to create new cable {cable_name} to {cable_type_name} type.\n"
                              f"Error: {res['status']} - {res['errorId']} - {res['message']}")
            self.create_cable(original_cable_data)
            self.logger.info(f"Original cable {cable_name} restored.")
            return
        self.logger.info(f"Cable {cable_name} successfully changed to type {cable_type_name}.")
        return res

    def _change_cable_type_from_id_range(self, id_from: str, id_to: str, cable_type_name: str) -> bool:
        id_prefix = id_from.split("-")[0]
        id_range = range(int(id_from.split("-")[1]), int(id_to.split("-")[1]) + 1)
        ids_to_change = list(id_range)
        for cable_number in ids_to_change:
            cable_id = f"{id_prefix}-{cable_number:04}"
            res = self._change_cable_type(cable_id, cable_type_name)
            if res is None:
                return False
        return True

    def _port_group_tree(self, port_group_list, get_ids=False):
        """
        Create a nested dictionary representation of port groups

        :param port_group_list: List of port group dictionaries
        :param get_ids: If True, get ids of port groups
        :return: dictionary
        """
        def find_subgroups(parent, port_group_list, found):
            subgroups = {}
            for port_group in port_group_list:
                if port_group['id'] is None and port_group['name'] not in found:
                    found.add(port_group['name'])
                    subgroups[port_group['name']] = {}
                elif port_group["parentId"] == parent and port_group['name'] not in found:
                    found.add(port_group['name'])
                    subgroups[port_group['name']] = find_subgroups(port_group["id"], port_group_list, found)
                    if get_ids:
                        subgroups[port_group['name']]['id'] = port_group['id']
            return subgroups

        return find_subgroups(None, port_group_list, {None})

    def _edit_template_json(self, template_json):
        new_property_group = []
        for property_group in template_json["propertyGroups"]:
            del property_group["id"]
            for property in property_group["properties"]:
                del property["id"]
            new_property_group.append(property_group)
        new_port_groups = self._port_group_tree(template_json["portGroups"])

        new_template = {"resource": {}, "ports": [], "port_groups": new_port_groups}
        new_template["resource"]["propertyGroups"] = new_property_group
        template_fields = ["description", "type", "parentId", "isShared",
                           "reservationTime", "configAssetId",
                           "configURI", "inheritConfig", "firmwareAssetId",
                           "firmwareURI", "inheritFirmware", "interface",
                           "l2SwitchId", "tags", "agentRequirements", "name"]
        for field in template_fields:
            if template_json[field] is not None:
                new_template["resource"][field] = template_json[field]
        return new_template

    def _get_template_ports(self, template_id):
        limit = 200
        resource_ports = []
        ports = self.get_template_ports(template_id,
                                        limit=200,
                                        includeProperties=True)
        resource_ports.extend(ports["ports"])
        total_all = ports["total"]
        offset = limit
        if total_all > limit:
            while offset < total_all:
                ports = self.get_template_ports(template_id,
                                                limit=200,
                                                offset=offset,
                                                includeProperties=True)
                resource_ports.extend(ports["ports"])
                offset += limit
        return resource_ports

    def _get_port_data(self, ports_info, templata_id):
        port_group = {}
        port_template = {}
        port_list = []
        for port in ports_info:
            port_info = {}
            port_info["name"] = port["name"]
            port_info["description"] = port["description"]
            port_info["isShared"] = port["isShared"]
            port_info["properties"] = []
            for property in port["properties"]:
                property_info = {}
                property_info["definitionId"] = ""
                property_info["name"] = property["name"]
                property_info["value"] = property["value"]
                port_info["properties"].append(property_info)
            if port["groupId"] not in port_group:
                port_group_info = self.get_template_port_group(templata_id,
                                                               port["groupId"])
                port_group[port["groupId"]] = port_group_info["name"]
                port_info["groupId"] = port_group_info["name"]
            else:
                port_info["groupId"] = port_group[port["groupId"]]
            if port["templateId"] not in port_template:
                port_template_info = self.get_template(port["templateId"])
                port_template[port["templateId"]] = port_template_info["name"]
                port_info["templateId"] = port_template_info["name"]
            else:
                port_info["templateId"] = port_template[port["templateId"]]
            port_list.append(port_info)
        port_group_list = list(port_group.values())
        port_template_list = list(port_template.values())
        return {"ports": port_list,
                "port_groups": port_group_list,
                "port_templates": port_template_list}

    def _delete_ports_and_groups(self, template_id):
        current_template = self.get_template(template_id)
        existing_port_group_tree = self._port_group_tree(current_template["portGroups"], get_ids=True)
        port_group_ids = {}
        for port_group, info_and_subgroups in existing_port_group_tree.items():
            if 'id' in info_and_subgroups:  # 'No group' ports handled separately
                self.delete_template_port_group(template_id, info_and_subgroups['id'])
            else:
                port_group_ids[port_group] = None

        template_ports = self.get_template_ports(template_id, limit=200)["ports"]
        for port_dict in template_ports:
            self.delete_template_port(template_id, port_dict['id'])

        return port_group_ids

    def _create_port_groups(self, template_id, port_groups_dict):
        port_group_ids = self._delete_ports_and_groups(template_id)

        def create_group(group_tree, parent_group=None):
            parent_group_id = port_group_ids.get(parent_group)
            for group_name, subgroups in group_tree.items():
                if group_name not in port_group_ids:
                    body = {"name": group_name, "parentId": parent_group_id}
                    port_group_info = self.create_template_port_group(template_id, body)
                    port_group_ids[group_name] = port_group_info["id"]
                    if subgroups:
                        create_group(subgroups, group_name)

        create_group(port_groups_dict)
        return port_group_ids

    def _get_templates_info(self, templates_name_list):
        templates_info = {}
        for template_name in templates_name_list:
            template = self.get_templates(filter=f'name::{template_name}')
            if len(template["templates"]) == 1:
                tmp_id = template["templates"][0]["id"]
                templates_info[template_name] = self.get_template(tmp_id)
            else:
                self.logger.error(f"Template {template_name} not found.")
        return templates_info

    def _delete_extra_ports(self,
                            template_id,
                            port_data,
                            created_tempalte_ports):
        ports_id_list = []
        for c_port in created_tempalte_ports:
            for port in port_data:
                if c_port["name"] == port["name"]:
                    continue
            ports_id_list.append(c_port["id"])
        if ports_id_list != []:
            data_body = {"ids": ports_id_list}
            delete_result = self.delete_template_ports(template_id,
                                                       body=data_body)
        return ports_id_list

    def _generate_port_data_body(self,
                                 port_data,
                                 port_groups_dict,
                                 port_templates_dict,
                                 created_template_ports,
                                 template_id):

        if created_template_ports != []:
            delete_ports = self._get_actual_port_group_and_template_id(port_data,
                                                                       port_groups_dict,
                                                                       port_templates_dict,
                                                                       created_template_ports)
            if delete_ports != {}:
                data_body = {"ids": []}
                for k, data in delete_ports.items():
                    data_body["ids"].append(data["port_id"])
                try:
                    delete_result = self.delete_template_ports(template_id, body=data_body)
                except Exception as e:
                    print(f'Port delete failed: {e}')

                for k, delete_data in delete_ports.items():
                    for index, port in enumerate(created_template_ports):
                        if port['id'] == delete_data["port_id"]:
                            del created_template_ports[index]
                            break

        existing_port_list = []
        for created_port in created_template_ports:
            existing_port_list.append(created_port["name"])
        port_data_body = []
        for port in port_data:
            if port["name"] in existing_port_list:
                continue
            port["groupId"] = self._get_port_group_id(port["groupId"],
                                                      port_groups_dict)
            port_template_data = self._get_port_template_data(port,
                                                              port_templates_dict)
            port["templateId"] = port_template_data["id"]
            port["properties"] = self._update_port_properties(port["properties"],
                                                              port_template_data)
            port_data_body.append(port)
        return port_data_body

    def _update_port_properties(self, port_properties, port_template_data):
        updated_properties = []
        for property in port_properties:
            for property_group in port_template_data["propertyGroups"]:
                for template_property in property_group["properties"]:
                    if property["name"] == template_property["name"]:
                        property["definitionId"] = template_property["id"]
                        updated_properties.append(property)
                        break
        return updated_properties

    def _get_port_group_id(self, port_group_name, port_groups_dict):
        for key, value in port_groups_dict.items():
            if key == port_group_name:
                return value

    def _get_port_template_data(self, port_data, port_templates_dict):
        for key, value in port_templates_dict.items():
            if key == port_data["templateId"]:
                return value

    def _add_to_u(self, shelf_list, number, isLRF, needzero=""):
        shelf_list.append(f"U{needzero}{number}")
        if isLRF:
            shelf_list.append(f'U{needzero}{number}L')
            shelf_list.append(f'U{needzero}{number}R')
            shelf_list.append(f'U{needzero}{number}F')

    @staticmethod
    def _change_cable_json(json, new_name):
        json_edited = deepcopy(json)
        json_edited.update({'name': new_name})
        return json_edited

    def _template_resources_self_to_file(self, template, property_name):
        property_dict = {}
        devices = self._get_device_list(template["id"])
        property_dict["devices"] = len(devices)
        if len(devices) == 0:
            print(f'No devices under {template["name"]}')
            return property_dict
        for device in devices:
            for property in device["properties"]:
                if property["name"].lower() == property_name.lower():
                    property_dict[device["name"]] = property["value"]
        if property_dict != {}:
            return property_dict
        else:
            print(f'{template["name"]} resourses do not have ' +
                  f'{property_name} property')
            return 0

    def _get_device_list(self, parent_template_id):
        limit = 200
        devices = []
        resources = self.get_devices(limit=200,
                                     filter=f'templateId::{parent_template_id}',
                                     includeProperties=True)
        devices.extend(resources["devices"])
        total_all = resources["total"]
        offset = limit
        if total_all > limit:
            while offset < total_all:
                resources = self.get_devices(limit=200,
                                             filter=f'templateId::{parent_template_id}',
                                             includeProperties=True, offset=offset)
                devices.extend(resources["devices"])
                offset += limit
        return devices

    def _get_actual_port_group_and_template_id(self,
                                               port_data,
                                               port_groups,
                                               port_templates,
                                               created_ports):
        port_dict = {}
        for port in port_data:
            import_group_name = port["groupId"]
            created_port_gid = ""
            for created_port in created_ports:
                if port["name"] == created_port["name"]:
                    created_port_gid = created_port["groupId"]
                    break
            if created_port_gid != port_groups[import_group_name]:
                for key, temp_data in port_templates.items():
                    for property in temp_data["propertyGroups"]:
                        for prop in property["properties"]:
                            if prop["name"] == "Port Type" and prop["defaultValue"] == port["groupId"]:
                                port_dict[port["name"]] = {"port_id": created_port["id"],
                                                           "group_id":  port_groups[port["groupId"]],
                                                           "template_id": temp_data["id"]}
                                break
        return port_dict

    def _get_template_id_by_name(self, template_name):
        templates = self.get_templates(filter=f'name::{template_name}')
        if templates["templates"] != []:
            for template in templates["templates"]:
                if template["name"] == template_name:
                    return template["id"]
        msg = f"Not found template: {template_name}"
        self.logger.error(msg)
        raise Exception(msg)

    def _get_dropdown_available_values(self, template_info, property_name):
        for property_group in template_info["propertyGroups"]:
            for property in property_group["properties"]:
                if property["name"] == property_name:
                    return property["availableValues"]
        raise Exception(f'Property {property_name} not found in template' +
                        f'{template_info["name"]}')
